function evaluerExpression(expr) {
  if (typeof expr !== "string") {
    throw new TypeError("L'expression doit etre une chaine de caracteres");
  }

  let position = 0;
  const longueur = expr.length;

  function ignorerEspaces() {
    while (position < longueur && /\s/.test(expr[position])) {
      position += 1;
    }
  }

  function lireNombre() {
    ignorerEspaces();
    const debut = position;
    let chiffresLus = 0;

    while (
      position < longueur &&
      expr[position] >= "0" &&
      expr[position] <= "9"
    ) {
      chiffresLus += 1;
      position += 1;
    }

    if (expr[position] === ".") {
      position += 1;
      while (
        position < longueur &&
        expr[position] >= "0" &&
        expr[position] <= "9"
      ) {
        chiffresLus += 1;
        position += 1;
      }
    }

    if (chiffresLus === 0) {
      throw new SyntaxError("Nombre invalide");
    }

    if (expr[position] === "e" || expr[position] === "E") {
      position += 1;
      if (expr[position] === "+" || expr[position] === "-") {
        position += 1;
      }

      const debutExposant = position;
      while (
        position < longueur &&
        expr[position] >= "0" &&
        expr[position] <= "9"
      ) {
        position += 1;
      }

      if (position === debutExposant) {
        throw new SyntaxError("Exposant invalide");
      }
    }

    return Number(expr.slice(debut, position));
  }

  function analyserFacteur() {
    ignorerEspaces();

    if (position >= longueur) {
      throw new SyntaxError("Expression incomplete");
    }

    if (expr[position] === "+" || expr[position] === "-") {
      const operateur = expr[position];
      position += 1;
      const valeur = analyserFacteur();
      return operateur === "-" ? -valeur : valeur;
    }

    if (expr[position] === "(") {
      position += 1;
      const valeur = analyserExpression();
      ignorerEspaces();

      if (expr[position] !== ")") {
        throw new SyntaxError("Parenthese fermante manquante");
      }

      position += 1;
      return valeur;
    }

    return lireNombre();
  }

  function analyserTerme() {
    let valeur = analyserFacteur();

    while (true) {
      ignorerEspaces();
      if (expr[position] === "*") {
        position += 1;
        valeur *= analyserFacteur();
      } else if (expr[position] === "/") {
        position += 1;
        valeur /= analyserFacteur();
      } else {
        break;
      }
    }

    return valeur;
  }

  function analyserExpression() {
    let valeur = analyserTerme();

    while (true) {
      ignorerEspaces();
      if (expr[position] === "+") {
        position += 1;
        valeur += analyserTerme();
      } else if (expr[position] === "-") {
        position += 1;
        valeur -= analyserTerme();
      } else {
        break;
      }
    }

    return valeur;
  }

  const resultat = analyserExpression();
  ignorerEspaces();

