function dijkstra(graphe, depart) {
  if (!graphe || typeof graphe !== "object") {
    throw new TypeError("Le graphe doit etre un objet");
  }

  const source = String(depart);
  const sommets = new Set([source]);

  for (const sommet of Object.keys(graphe)) {
    sommets.add(sommet);
  }

  for (const voisins of Object.values(graphe)) {
    if (voisins !== null && typeof voisins === "object") {
      for (const voisin of Object.keys(voisins)) {
        sommets.add(voisin);
      }
    }
  }

  const distances = new Map();
  for (const sommet of sommets) {
    distances.set(sommet, Infinity);
  }
  distances.set(source, 0);

  const tas = [];

  function pousser(sommet, priorite) {
    const element = { sommet, priorite };
    tas.push(element);

    let indice = tas.length - 1;
    while (indice > 0) {
      const parent = Math.floor((indice - 1) / 2);

      if (tas[parent].priorite <= tas[indice].priorite) {
        break;
      }

      const temporaire = tas[parent];
      tas[parent] = tas[indice];
      tas[indice] = temporaire;
      indice = parent;
    }
  }

  function retirerMinimum() {
    const minimum = tas[0];
    const dernier = tas.pop();

    if (tas.length > 0) {
      tas[0] = dernier;
      let indice = 0;

      while (true) {
        let plusPetit = indice;
        const gauche = 2 * indice + 1;
        const droit = 2 * indice + 2;

        if (
          gauche < tas.length &&
          tas[gauche].priorite < tas[plusPetit].priorite
        ) {
          plusPetit = gauche;
        }

        if (
          droit < tas.length &&
          tas[droit].priorite < tas[plusPetit].priorite
        ) {
          plusPetit = droit;
        }

        if (plusPetit === indice) {
          break;
        }

        const temporaire = tas[indice];
        tas[indice] = tas[plusPetit];
        tas[plusPetit] = temporaire;
        indice = plusPetit;
      }
    }

    return minimum.sommet;
  }

  const estUnePropriete = Object.prototype.hasOwnProperty;
  pousser(source, 0);

  while (tas.length > 0) {
    const sommet = retirerMinimum();
    const distanceActuelle = distances.get(sommet);

    if (distanceActuelle === undefined) {
      continue;
    }

    const voisins = estUnePropriete.call(graphe, sommet)
      ? graphe[sommet]
      : undefined;

    if (voisins !== null && typeof voisins === "object") {
      for (const [voisin, poids] of Object.entries(voisins)) {
        const poidsNumerique = Number(poids);

        if (!Number.isFinite(poidsNumerique) || poidsNumerique < 0) {
          throw new Error("Dijkstra necessite des poids non negatifs");
        }

        const candidate = distanceActuelle + poidsNumerique;

        if (candidate < distances.get(voisin)) {
          distances.set(voisin, candidate);
          pousser(voisin, candidate);
        }
      }
    }
  }

  return Object.fromEntries(
    Array.from(sommets, (sommet) => [sommet, distances.get(sommet)])
  );
}
