function dijkstra(graphe, depart) {
  const sommets = new Set();
  const adjacences = new Map();
  const entrees = graphe === null || graphe === undefined
    ? []
    : Object.entries(graphe);

  for (const [sommet, voisins] of entrees) {
    sommets.add(sommet);
    const voisinsValides = voisins !== null && typeof voisins === "object"
      ? voisins
      : {};
    adjacences.set(sommet, voisinsValides);

    for (const voisin of Object.keys(voisinsValides)) {
      sommets.add(voisin);
    }
  }

  if (!sommets.has(depart)) {
    sommets.add(depart);
    adjacences.set(depart, {});
  }

  const distances = new Map();
  for (const sommet of sommets) {
    distances.set(sommet, Infinity);
  }
  distances.set(depart, 0);

  const file = [{ sommet: depart, distance: 0 }];
  const visites = new Set();

  function pousser(element) {
    file.push(element);
    let index = file.length - 1;

    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);
      if (file[parent].distance <= file[index].distance) {
        break;
      }
      [file[parent], file[index]] = [file[index], file[parent]];
      index = parent;
    }
  }

  function retirerMinimum() {
    const minimum = file[0];
    const dernier = file.pop();

    if (file.length > 0) {
      file[0] = dernier;
      let index = 0;

      while (true) {
        const gauche = 2 * index + 1;
        const droit = 2 * index + 2;
        let plusPetit = index;

        if (
          gauche < file.length &&
          file[gauche].distance < file[plusPetit].distance
        ) {
          plusPetit = gauche;
        }
        if (
          droit < file.length &&
          file[droit].distance < file[plusPetit].distance
        ) {
          plusPetit = droit;
        }
        if (plusPetit === index) {
          break;
        }

        [file[index], file[plusPetit]] = [file[plusPetit], file[index]];
        index = plusPetit;
      }
    }

    return minimum;
  }

  while (file.length > 0) {
    const { sommet, distance } = retirerMinimum();

    if (visites.has(sommet) || distance !== distances.get(sommet)) {
      continue;
    }

    visites.add(sommet);
    const voisins = adjacences.get(sommet) || {};

    for (const [voisin, poids] of Object.entries(voisins)) {
      if (typeof poids !== "number" || poids < 0) {
        throw new Error("Dijkstra necessita des poids non negatifs");
      }

      const nouvelleDistance = distance + poids;
      if (nouvelleDistance < distances.get(voisin)) {
        distances.set(voisin, nouvelleDistance);
        pousser({ sommet: voisin, distance: nouvelleDistance });
      }
    }
  }

  return Object.fromEntries(
    Array.from(sommets, (sommet) => [sommet, distances.get(sommet)])
  );
}
