        temporaire[k++] = resultat[j++];
      }
    }

    while (i < milieu) temporaire[k++] = resultat[i++];
    while (j < droite) temporaire[k++] = resultat[j++];

    for (let index = gauche; index < droite; index++) {
      resultat[index] = temporaire[index];
    }
  }

  function trier(gauche, droite) {
    if (droite - gauche <= 1) return;
    const milieu = gauche + Math.floor((droite - gauche) / 2);
    trier(gauche, milieu);
    trier(milieu, droite);
    fusionner(gauche, milieu, droite);
  }

  trier(0, resultat.length);
  return resultat;
}

