function optimisation_extreme(arr, target) {
  const nombresVus = new Set();

  for (const nombre of arr) {
    if (nombresVus.has(target - nombre)) {
      return true;
    }
    nombresVus.add(nombre);
  }

  return false;
}

function fusionnerIntervalles(tab) {
  const intervalles = [];
  for (let i = 0; i < tab.length; i++) {
    intervalles.push([tab[i][0], tab[i][1]]);
  }

  const temporaire = new Array(intervalles.length);

  function fusionner(gauche, milieu, droite) {
    let i = gauche;
    let j = milieu;
    let k = gauche;

    while (i < milieu && j < droite) {
      if (intervalles[i][0] <= intervalles[j][0]) {
        temporaire[k++] = intervalles[i++];
      } else {
        temporaire[k++] = intervalles[j++];
      }
    }

    while (i < milieu) temporaire[k++] = intervalles[i++];
    while (j < droite) temporaire[k++] = intervalles[j++];

    for (let index = gauche; index < droite; index++) {
      intervalles[index] = temporaire[index];
    }
  }

  function trier(gauche, droite) {
    if (droite - gauche <= 1) return;
    const milieu = gauche + Math.floor((droite - gauche) / 2);
    trier(gauche, milieu);
    trier(milieu, droite);
    fusionner(gauche, milieu, droite);
  }

  trier(0, intervalles.length);

  const resultat = [];
  for (const [debut, fin] of intervalles) {
    const derniere = resultat[resultat.length - 1];
    if (!derniere || debut > derniere[1]) {
      resultat.push([debut, fin]);
    } else if (fin > derniere[1]) {
      derniere[1] = fin;
    }
  }

  return resultat;
}

function prefixeCommun(tab) {
  if (tab.length === 0) return '';

  let prefixe = tab[0];
  for (let i = 1; i < tab.length; i++) {
    while (tab[i].indexOf(prefixe) !== 0) {
      prefixe = prefixe.slice(0, -1);
      if (prefixe === '') return '';
    }
  }

  return prefixe;
}

function nombreDeBits1(n) {
  let nombre = 0;

  while (n > 0) {
    if (n % 2 === 1) nombre++;
    n = Math.floor(n / 2);
  }

  return nombre;
}

function medianeDeuxTries(a, b) {
  if (a.length > b.length) return medianeDeuxTries(b, a);

  const m = a.length;
  const n = b.length;
  const total = m + n;
  const moitie = Math.floor(total / 2);
  let bas = 0;
  let haut = m;

  while (bas <= haut) {
    const i = Math.floor((bas + haut) / 2);
    const j = moitie - i;

    const aGauche = i === 0 ? -Infinity : a[i - 1];
    const aDroite = i === m ? Infinity : a[i];
    const bGauche = j === 0 ? -Infinity : b[j - 1];
    const bDroite = j === n ? Infinity : b[j];

    if (aGauche <= bDroite && bGauche <= aDroite) {
      if (total % 2 === 1) return Math.min(aDroite, bDroite);
      const gauche = Math.max(aGauche, bGauche);
      const droite = Math.min(aDroite, bDroite);
      return (gauche + droite) / 2;
    }

    if (aGauche > bDroite) {
      haut = i - 1;
    } else {
      bas = i + 1;
    }
  }

  throw new Error('Les tableaux fournis ne permettent pas de calculer une médiane.');
}

function plusLongueSousSuiteCroissante(tab) {
  const queues = [];
  let longueur = 0;

  for (const valeur of tab) {
    let bas = 0;
    let haut = longueur;

    while (bas < haut) {
      const milieu = Math.floor((bas + haut) / 2);
      if (queues[milieu] < valeur) {
        bas = milieu + 1;
      } else {
        haut = milieu;
      }
    }

    queues[bas] = valeur;
    if (bas === longueur) longueur++;
  }

  return longueur;
}
